import { AgentVaultBearerConfigSchema } from "./agent-vault-credential-schemas";

describe("bearer credential config", () => {
  test("Authorization and Bearer settle together when neither is given", () => {
    expect(AgentVaultBearerConfigSchema.parse({})).toEqual({
      headerName: "Authorization",
      headerPrefix: "Bearer"
    });
  });

  test("naming Authorization outright still gets the scheme it belongs to", () => {
    expect(AgentVaultBearerConfigSchema.parse({ headerName: "authorization" })).toEqual({
      headerName: "authorization",
      headerPrefix: "Bearer"
    });
  });

  // The scheme is RFC 6750's for Authorization. A key in its own header is not a bearer token in that
  // sense, and an API given "Bearer abc" where it wanted "abc" rejects the request.
  test("a header of the caller's own gets no scheme they did not ask for", () => {
    expect(AgentVaultBearerConfigSchema.parse({ headerName: "X-Api-Key" })).toEqual({
      headerName: "X-Api-Key",
      headerPrefix: ""
    });
  });

  test("an explicit prefix is kept, on any header", () => {
    expect(AgentVaultBearerConfigSchema.parse({ headerName: "X-Api-Key", headerPrefix: "Token" })).toEqual({
      headerName: "X-Api-Key",
      headerPrefix: "Token"
    });
    expect(AgentVaultBearerConfigSchema.parse({ headerPrefix: "" })).toEqual({
      headerName: "Authorization",
      headerPrefix: ""
    });
  });
});

import { Knex } from "knex";

import { TableName } from "../schemas";
import { createOnUpdateTrigger, dropOnUpdateTrigger } from "../utils";

export async function up(knex: Knex): Promise<void> {
  const hasAllowedMethods = await knex.schema.hasColumn(TableName.AgentVaultService, "allowedMethods");
  const hasAllowedPathPrefixes = await knex.schema.hasColumn(TableName.AgentVaultService, "allowedPathPrefixes");

  if (!hasAllowedMethods || !hasAllowedPathPrefixes) {
    await knex.schema.alterTable(TableName.AgentVaultService, (t) => {
      // NULL is the only "unrestricted": an empty array is never stored, so there is one representation of "all".
      // Arrays rather than the comma-separated strings hostPattern uses, because a comma is legal in a path.
      if (!hasAllowedMethods) t.specificType("allowedMethods", "text[]");
      if (!hasAllowedPathPrefixes) t.specificType("allowedPathPrefixes", "text[]");
    });
  }

  if (!(await knex.schema.hasTable(TableName.AgentVaultServiceCustomHeader))) {
    await knex.schema.createTable(TableName.AgentVaultServiceCustomHeader, (t) => {
      t.uuid("id", { primaryKey: true }).defaultTo(knex.fn.uuid());

      t.uuid("serviceId").notNullable();
      t.foreign("serviceId").references("id").inTable(TableName.AgentVaultService).onDelete("CASCADE");
      t.index("serviceId");

      t.string("name", 128).notNullable();
      t.string("prefix", 64).notNullable();

      t.binary("encryptedValue").notNullable();

      t.integer("position").notNullable();

      t.timestamps(true, true, true);
    });

    await createOnUpdateTrigger(knex, TableName.AgentVaultServiceCustomHeader);
  }

  if (!(await knex.schema.hasTable(TableName.AgentVaultServiceSubstitution))) {
    await knex.schema.createTable(TableName.AgentVaultServiceSubstitution, (t) => {
      t.uuid("id", { primaryKey: true }).defaultTo(knex.fn.uuid());

      t.uuid("serviceId").notNullable();
      t.foreign("serviceId").references("id").inTable(TableName.AgentVaultService).onDelete("CASCADE");
      t.index("serviceId");

      t.string("placeholder", 255).notNullable();
      t.specificType("surfaces", "text[]").notNullable();

      t.binary("encryptedValue").notNullable();

      t.integer("position").notNullable();

      t.timestamps(true, true, true);
    });

    await createOnUpdateTrigger(knex, TableName.AgentVaultServiceSubstitution);
  }
}

export async function down(knex: Knex): Promise<void> {
  await knex.schema.dropTableIfExists(TableName.AgentVaultServiceSubstitution);
  await dropOnUpdateTrigger(knex, TableName.AgentVaultServiceSubstitution);

  await knex.schema.dropTableIfExists(TableName.AgentVaultServiceCustomHeader);
  await dropOnUpdateTrigger(knex, TableName.AgentVaultServiceCustomHeader);

  const hasAllowedMethods = await knex.schema.hasColumn(TableName.AgentVaultService, "allowedMethods");
  const hasAllowedPathPrefixes = await knex.schema.hasColumn(TableName.AgentVaultService, "allowedPathPrefixes");

  if (hasAllowedMethods || hasAllowedPathPrefixes) {
    await knex.schema.alterTable(TableName.AgentVaultService, (t) => {
      if (hasAllowedMethods) t.dropColumn("allowedMethods");
      if (hasAllowedPathPrefixes) t.dropColumn("allowedPathPrefixes");
    });
  }
}

import { describe, expect, test } from "vitest";

import {
  AGENT_VAULT_SESSION_LOG_MAX_CHUNK_BYTES,
  AGENT_VAULT_SESSION_LOG_MIN_CHUNK_BYTES
} from "./agent-vault-session-log-constants";
import { encodeHistoryCursor, encodeTailCursor } from "./agent-vault-session-log-fns";
import {
  AgentVaultSessionLogChunkCreateSchema,
  AgentVaultSessionLogHistoryQuerySchema,
  AgentVaultSessionLogSettingsUpdateSchema,
  AgentVaultSessionLogTailQuerySchema
} from "./agent-vault-session-log-schemas";

const validChunk = {
  chunkId: "01a0a9c5-231d-7abc-8def-0123456789ab",
  endedAt: "2026-09-16T10:31:00.000Z",
  ciphertextBytes: 4096,
  ciphertextSha256: "47DEQpj8HBSa+/TImW+5JCeuQeRkm5NMpJWZG3hSuFU"
};

describe("the chunk create body", () => {
  test("accepts a well-formed chunk and coerces the timestamp to a date", () => {
    const parsed = AgentVaultSessionLogChunkCreateSchema.parse(validChunk);
    expect(parsed.endedAt).toBeInstanceOf(Date);
    expect(parsed.endedAt.toISOString()).toBe("2026-09-16T10:31:00.000Z");
  });

  test.each([
    { field: "chunkId", value: "not-a-uuid", why: "a chunk id has to be a UUIDv7 so it sorts by time" },
    { field: "chunkId", value: "3f2b8c1e-9d4a-4e6b-a1c7-5f0e2d9b8a64", why: "a v4 UUID does not sort by time" },
    {
      field: "chunkId",
      value: "01A0A9C5-231D-7ABC-8DEF-0123456789AB",
      why: "the browser rebuilds the AAD from the lowercase id in the object name"
    },
    {
      field: "ciphertextBytes",
      value: AGENT_VAULT_SESSION_LOG_MIN_CHUNK_BYTES - 1,
      why: "smaller than an IV, '[]' and a tag"
    },
    { field: "ciphertextBytes", value: AGENT_VAULT_SESSION_LOG_MAX_CHUNK_BYTES + 1, why: "over the size ceiling" },
    {
      field: "ciphertextSha256",
      value: "47DEQpj8HBSa+/TImW+5JCeuQeRkm5NMpJWZG3hSuFU=",
      why: "padded base64 is the wrong width"
    },
    {
      field: "ciphertextSha256",
      value: "47DEQpj8HBSa+/TImW+5JCeuQeRkm5NMpJWZG3hSuF",
      why: "42 characters is not 32 bytes"
    },
    {
      field: "ciphertextSha256",
      value: "47DEQpj8HBSa-/TImW-5JCeuQeRkm5NMpJWZG3hSuFU",
      why: "url-safe base64 is a different alphabet"
    },
    { field: "ciphertextSha256", value: undefined, why: "every chunk carries its digest" }
  ])("rejects $field: $why", ({ field, value }) => {
    expect(AgentVaultSessionLogChunkCreateSchema.safeParse({ ...validChunk, [field]: value }).success).toBe(false);
  });

  test("drops a field the contract does not name, so a caller can't choose the object key", () => {
    const parsed = AgentVaultSessionLogChunkCreateSchema.parse({ ...validChunk, objectKey: "attacker/controlled" });
    expect(parsed).not.toHaveProperty("objectKey");
  });
});

describe("the session logs history query", () => {
  test("accepts a history query with no cursor", () => {
    expect(AgentVaultSessionLogHistoryQuerySchema.parse({})).toEqual({ cursor: undefined });
  });

  test("reads a cursor back as the name to continue after", () => {
    const after = "8208694117999_01a11226-9990-7a3f-8c21-4e6f9b2d1a07.e91f3c20-7d4b-4a8e-9f1c-3b5d7e2a6c48.json.enc";
    expect(AgentVaultSessionLogHistoryQuerySchema.parse({ cursor: encodeHistoryCursor(after) }).cursor).toBe(after);
  });

  test.each([
    "yesterday",
    Buffer.from('{"v":1,"m":"h","id":"01a0a9c5-231d-7abc-8def-0123456789ab"}').toString("base64url"),
    Buffer.from('{"v":2,"m":"h","after":""}').toString("base64url"),
    Buffer.from(JSON.stringify({ v: 2, m: "h", after: "x".repeat(1025) })).toString("base64url")
  ])("rejects a cursor it did not issue: %s", (cursor) => {
    expect(AgentVaultSessionLogHistoryQuerySchema.safeParse({ cursor }).success).toBe(false);
  });

  test("says where a tail cursor belongs", () => {
    const result = AgentVaultSessionLogHistoryQuerySchema.safeParse({ cursor: encodeTailCursor("1791278402731-0") });
    expect(result.success).toBe(false);
    expect(result.error?.issues[0].message).toMatch(/session logs tail endpoint/);
  });
});

describe("the session logs tail query", () => {
  test("accepts a tail query with no cursor", () => {
    expect(AgentVaultSessionLogTailQuerySchema.parse({})).toEqual({ cursor: undefined });
  });

  test("reads a cursor back as the feed entry to continue after", () => {
    expect(AgentVaultSessionLogTailQuerySchema.parse({ cursor: encodeTailCursor("1791278402731-3") }).cursor).toBe(
      "1791278402731-3"
    );
  });

  test.each([
    "yesterday",
    Buffer.from('{"v":1,"m":"t","at":"2026-09-25T10:00:00.123Z"}').toString("base64url"),
    Buffer.from('{"v":2,"m":"t","id":"1791278402731"}').toString("base64url"),
    Buffer.from('{"v":2,"m":"t","id":"99999999999999999-0"}').toString("base64url")
  ])("rejects a cursor it did not issue: %s", (cursor) => {
    expect(AgentVaultSessionLogTailQuerySchema.safeParse({ cursor }).success).toBe(false);
  });

  test("says where a history cursor belongs", () => {
    const result = AgentVaultSessionLogTailQuerySchema.safeParse({
      cursor: encodeHistoryCursor("8208694117999_01a11226-9990-7a3f-8c21-4e6f9b2d1a07")
    });
    expect(result.success).toBe(false);
    expect(result.error?.issues[0].message).toMatch(/session logs endpoint instead/);
  });
});

describe("the settings patch", () => {
  test("every field is optional, so an empty patch is valid", () => {
    expect(AgentVaultSessionLogSettingsUpdateSchema.parse({})).toEqual({});
  });

  test("accepts null for the connection, which detaches it", () => {
    expect(AgentVaultSessionLogSettingsUpdateSchema.parse({ appConnectionId: null }).appConnectionId).toBeNull();
  });

  test.each([
    { value: "..", why: "the whole prefix is a traversal" },
    { value: "logs/../../etc", why: "a traversal segment in the middle" },
    { value: "logs/../secrets", why: "climbing out of the prefix" },
    { value: ".", why: "the whole prefix is a current-folder reference" },
    { value: "./logs", why: "a leading '.' folder, which browsers drop from the download link" },
    { value: "logs/./agent-vault", why: "a '.' folder in the middle" },
    { value: "logs/.", why: "a trailing '.' folder" },
    { value: "/logs", why: "a slash at the start" },
    { value: "logs/", why: "a slash at the end" },
    { value: "logs//agent-vault", why: "an empty folder between two slashes" },
    { value: "/", why: "only a slash" },
    { value: "logs/\u0000", why: "a control character" },
    { value: "team*", why: "an asterisk, which is a wildcard in the suggested IAM policy" },
    { value: "a".repeat(513), why: "longer than 512 characters" }
  ])("rejects a key prefix: $why", ({ value }) => {
    expect(AgentVaultSessionLogSettingsUpdateSchema.safeParse({ keyPrefix: value }).success).toBe(false);
  });

  test.each(["logs", "logs/agent-vault", "a.b-c_d", "", ".hidden/logs", "logs/...", "logs.v2"])(
    "accepts the key prefix %s",
    (keyPrefix) => {
      expect(AgentVaultSessionLogSettingsUpdateSchema.safeParse({ keyPrefix }).success).toBe(true);
    }
  );

  test("accepts a key prefix of exactly 512 characters", () => {
    expect(AgentVaultSessionLogSettingsUpdateSchema.safeParse({ keyPrefix: "a".repeat(512) }).success).toBe(true);
  });

  test("rejects a region that is not an AWS region", () => {
    expect(AgentVaultSessionLogSettingsUpdateSchema.safeParse({ region: "moon-base-1" }).success).toBe(false);
  });

  test.each([
    { value: "ab", why: "shorter than 3 characters" },
    { value: "a".repeat(64), why: "longer than 63 characters" },
    { value: "My-Bucket", why: "uppercase letters" },
    { value: "my_bucket", why: "an underscore" },
    { value: "-bucket", why: "a leading hyphen" },
    { value: "bucket.", why: "a trailing dot" }
  ])("rejects a bucket name with $why", ({ value }) => {
    expect(AgentVaultSessionLogSettingsUpdateSchema.safeParse({ bucket: value }).success).toBe(false);
  });

  test.each(["session-logs-bucket", "a.b-c", "a".repeat(63)])("accepts the bucket name %s", (bucket) => {
    expect(AgentVaultSessionLogSettingsUpdateSchema.safeParse({ bucket }).success).toBe(true);
  });
});

import { describe, expect, test, vi } from "vitest";

import {
  generateSessionLogKey,
  openSessionLogKey,
  unwrapSessionLogKey,
  wrapSessionLogKey
} from "./agent-vault-session-log-secrets";

vi.mock("@app/lib/logger", () => ({ logger: { error: vi.fn() } }));

// The real KMS wrap is authenticated encryption; passing bytes through leaves only the label check under test.
const passThroughKms = {
  createCipherPairWithDataKey: async () => ({
    encryptor: ({ plainText }: { plainText: Buffer }) => ({ cipherTextBlob: Buffer.from(plainText) }),
    decryptor: ({ cipherTextBlob }: { cipherTextBlob: Buffer }) => Buffer.from(cipherTextBlob)
  })
} as never;

describe("session log keys", () => {
  test("a key opens for the session it was wrapped for", async () => {
    const sessionLogKey = generateSessionLogKey();
    const encryptedSessionLogKey = await wrapSessionLogKey(
      { projectId: "proj-1", sessionId: "sess-a", sessionLogKey },
      passThroughKms
    );

    const opened = await unwrapSessionLogKey(
      { projectId: "proj-1", sessionId: "sess-a", encryptedSessionLogKey },
      passThroughKms
    );
    expect(opened.equals(sessionLogKey)).toBe(true);
  });

  test("a key copied onto another session's row is refused rather than handed out", async () => {
    const encryptedSessionLogKey = await wrapSessionLogKey(
      { projectId: "proj-1", sessionId: "sess-a", sessionLogKey: generateSessionLogKey() },
      passThroughKms
    );

    await expect(
      unwrapSessionLogKey({ projectId: "proj-1", sessionId: "sess-b", encryptedSessionLogKey }, passThroughKms)
    ).rejects.toMatchObject({ name: "InternalServerError" });
  });

  test("a stored key without its session label is refused", () => {
    expect(() => openSessionLogKey({ sessionId: "sess-a", payload: generateSessionLogKey() })).toThrow();
  });
});

import { STSServiceException } from "@aws-sdk/client-sts";
import { describe, expect, test, vi } from "vitest";

import { ProjectType } from "@app/db/schemas";
import { AppConnection, AWSRegion } from "@app/services/app-connection/app-connection-enums";
import { getAwsConnectionConfig } from "@app/services/app-connection/aws/aws-connection-fns";

import { buildSessionLogStorage } from "./agent-vault-session-log-storage-fns";

vi.mock("@app/lib/logger", () => ({
  logger: { info: () => {}, warn: () => {}, error: () => {}, debug: () => {} }
}));
vi.mock("@app/services/app-connection/app-connection-fns", () => ({
  decryptAppConnection: vi.fn(async (raw: unknown) => raw)
}));
vi.mock("@app/services/app-connection/aws/aws-connection-fns", () => ({
  getAwsConnectionConfig: vi.fn()
}));
vi.mock("@app/lib/aws/s3", async (importOriginal) => ({
  ...(await importOriginal<typeof import("@app/lib/aws/s3")>()),
  createS3Bucket: vi.fn(() => ({}))
}));

describe("buildSessionLogStorage", () => {
  const config = { appConnectionId: "conn-1", bucket: "logs", region: AWSRegion.US_EAST_1, keyPrefix: null };
  const deps = {
    appConnectionDAL: {
      findById: vi.fn(async () => ({ id: "conn-1", name: "prod-logs", orgId: "org-1", app: AppConnection.AWS }))
    },
    kmsService: {}
  } as unknown as Parameters<typeof buildSessionLogStorage>[2];

  test("says which connection could not be used and what AWS said", async () => {
    vi.mocked(getAwsConnectionConfig).mockRejectedValueOnce(
      new STSServiceException({
        name: "AccessDenied",
        $fault: "client",
        $metadata: { httpStatusCode: 403 },
        message: "User is not authorized to perform: sts:AssumeRole"
      })
    );
    await expect(buildSessionLogStorage(config, "org-1", deps)).rejects.toMatchObject({
      name: "BadRequest",
      message:
        "Couldn't use the AWS connection 'prod-logs' for session logs: User is not authorized to perform: sts:AssumeRole"
    });
  });

  test.each([
    {
      why: "AWS throttles the call",
      error: new STSServiceException({
        name: "Throttling",
        $fault: "client",
        $metadata: { httpStatusCode: 400 },
        message: "Rate exceeded"
      })
    },
    { why: "the network drops it", error: Object.assign(new Error("connect ETIMEDOUT"), { code: "ETIMEDOUT" }) }
  ])("is a 500 to try again when $why", async ({ error }) => {
    vi.mocked(getAwsConnectionConfig).mockRejectedValueOnce(error);
    await expect(buildSessionLogStorage(config, "org-1", deps)).rejects.toMatchObject({
      name: "InternalServerError",
      message: "Couldn't reach AWS to use the connection 'prod-logs' for session logs. Try again in a bit."
    });
  });

  test("assumes the role with Agent Vault's External ID and timeouts, for its own connections too", async () => {
    vi.mocked(getAwsConnectionConfig).mockClear();
    vi.mocked(getAwsConnectionConfig).mockResolvedValueOnce({
      region: AWSRegion.US_EAST_1,
      credentials: { accessKeyId: "access-key", secretAccessKey: "secret-key", sessionToken: undefined }
    });
    vi.mocked(deps.appConnectionDAL.findById).mockResolvedValueOnce({
      id: "conn-1",
      name: "av-logs",
      orgId: "org-1",
      projectId: "av-proj",
      app: AppConnection.AWS
    } as never);
    await buildSessionLogStorage(config, "org-1", deps);
    expect(getAwsConnectionConfig).toHaveBeenCalledWith(
      expect.objectContaining({ projectType: ProjectType.AgentVault }),
      config.region,
      { stsRequestHandler: { connectionTimeout: 5_000, requestTimeout: 15_000, throwOnRequestTimeout: true } }
    );
  });

  test("keeps anything that is not from AWS out of the message", async () => {
    vi.mocked(getAwsConnectionConfig).mockRejectedValueOnce(new Error("kms_keys row missing"));
    await expect(buildSessionLogStorage(config, "org-1", deps)).rejects.toMatchObject({
      message: "Couldn't use the AWS connection 'prod-logs' for session logs: Infisical could not load its credentials"
    });
  });

  test.each([
    { why: "no longer exists", row: undefined },
    {
      why: "belongs to another organization",
      row: { id: "conn-1", name: "theirs", orgId: "org-2", app: AppConnection.AWS }
    }
  ])("treats a connection that $why as missing", async ({ row }) => {
    vi.mocked(getAwsConnectionConfig).mockClear();
    vi.mocked(deps.appConnectionDAL.findById).mockResolvedValueOnce(row as never);
    await expect(buildSessionLogStorage(config, "org-1", deps)).rejects.toMatchObject({
      name: "BadRequest",
      message: "The AWS connection used for session logs no longer exists. Choose another on the Settings page."
    });
    expect(getAwsConnectionConfig).not.toHaveBeenCalled();
  });

  test("refuses a connection that is not AWS", async () => {
    vi.mocked(getAwsConnectionConfig).mockClear();
    vi.mocked(deps.appConnectionDAL.findById).mockResolvedValueOnce({
      id: "conn-1",
      name: "github",
      orgId: "org-1",
      app: AppConnection.GitHub
    } as never);
    await expect(buildSessionLogStorage(config, "org-1", deps)).rejects.toMatchObject({
      name: "BadRequest",
      message: `The connection used for session logs is a ${AppConnection.GitHub} connection. Session logs require an AWS connection`
    });
    expect(getAwsConnectionConfig).not.toHaveBeenCalled();
  });
});

import RE2 from "re2";
import { z } from "zod";

import { AgentVaultCredentialType } from "./agent-vault-enums";

// credentialConfig is plaintext jsonb, read on the list page without a decrypt; encryptedCredential is
// the KMS-sealed secret, NULL exactly when the type is passthrough. The discriminator is a column rather
// than a field inside the blob, so a new credential type needs no migration.

// The characters RFC 7230 allows. Go's HTTP client refuses to send anything else, so a name saved
// without this check 502s every request through the service.
export const AGENT_VAULT_HEADER_NAME_RE = new RE2(/^[A-Za-z0-9!#$%&'*+.^_`|~-]+$/);

export const AGENT_VAULT_HEADER_NAME_MESSAGE =
  "A header name can't contain spaces or colons. Use letters, digits and dashes, as in X-API-Key.";

// A NUL is rejected by the jsonb write and 500s; a CR or LF saves fine and then makes Go refuse to send
// the header, so the credential silently never goes out. Both usually arrive by pasting.
// eslint-disable-next-line no-control-regex
export const AGENT_VAULT_NO_CONTROL_CHARS_RE = new RE2(/^[^\x00-\x1f\x7f]*$/);

export const AGENT_VAULT_NO_CONTROL_CHARS_MESSAGE =
  "This can't contain line breaks or other control characters. Check for a stray newline if you pasted it.";

const AGENT_VAULT_DEFAULT_HEADER_NAME = "Authorization";
const AGENT_VAULT_DEFAULT_HEADER_PREFIX = "Bearer";

const bearerHeaderName = z
  .string()
  .trim()
  .min(1)
  .max(128)
  .regex(AGENT_VAULT_HEADER_NAME_RE, AGENT_VAULT_HEADER_NAME_MESSAGE);

// The shape a stored bearer config has, where both halves are already settled.
export const AgentVaultBearerConfigFields = {
  headerName: bearerHeaderName.default(AGENT_VAULT_DEFAULT_HEADER_NAME),
  headerPrefix: z.string().trim().max(64).default("")
};

// Bearer is the scheme RFC 6750 defines for Authorization, so the two settle together on the way in.
// Naming another header leaves that scheme behind, and filling one in there would send a word the
// caller never asked for.
export const AgentVaultBearerConfigSchema = z
  .object({
    headerName: bearerHeaderName.default(AGENT_VAULT_DEFAULT_HEADER_NAME),
    headerPrefix: z.string().trim().max(64).optional()
  })
  .transform(({ headerName, headerPrefix }) => ({
    headerName,
    headerPrefix:
      headerPrefix ??
      (headerName.toLowerCase() === AGENT_VAULT_DEFAULT_HEADER_NAME.toLowerCase()
        ? AGENT_VAULT_DEFAULT_HEADER_PREFIX
        : "")
  }));

// Nothing plaintext: the username is sealed with the password, since for some services (Stripe, Postmark)
// the username is the key.
export const AgentVaultBasicConfigSchema = z.object({});

export const AgentVaultPassthroughConfigSchema = z.object({});

export const AgentVaultCredentialConfigSchema = z.discriminatedUnion("type", [
  z.object({ ...AgentVaultBearerConfigFields, type: z.literal(AgentVaultCredentialType.Bearer) }),
  AgentVaultBasicConfigSchema.extend({ type: z.literal(AgentVaultCredentialType.Basic) }),
  AgentVaultPassthroughConfigSchema.extend({ type: z.literal(AgentVaultCredentialType.Passthrough) })
]);

export type TAgentVaultCredentialConfig = z.infer<typeof AgentVaultCredentialConfigSchema>;

export const AgentVaultSecretSchema = z.discriminatedUnion("type", [
  z.object({ type: z.literal(AgentVaultCredentialType.Bearer), value: z.string().min(1).max(8192) }),
  z.object({
    type: z.literal(AgentVaultCredentialType.Basic),
    username: z.string().max(256),
    password: [REDACTED]
  })
]);

export type TAgentVaultSecret = [REDACTED] AgentVaultSecretSchema>;

import { z } from "zod";

import { SecretSyncs } from "@app/lib/api-docs";
import { AppConnection } from "@app/services/app-connection/app-connection-enums";
import { SecretSync } from "@app/services/secret-sync/secret-sync-enums";
import {
  BaseSecretSyncSchema,
  GenericCreateSecretSyncFieldsSchema,
  GenericUpdateSecretSyncFieldsSchema
} from "@app/services/secret-sync/secret-sync-schemas";
import { TSyncOptionsConfig } from "@app/services/secret-sync/secret-sync-types";

import { SECRET_SYNC_NAME_MAP } from "../secret-sync-maps";

const AzureEntraIdScimSyncDestinationConfigSchema = z.object({
  servicePrincipalId: z
    .string()
    .uuid()
    .trim()
