const API_ROUTES = [
  { method: "GET" as const, url: "/api/v1/admin/config", requestUrl: "/api/v1/admin/config" },
  { method: "GET" as const, url: "/api/v2/users/me/organizations", requestUrl: "/api/v2/users/me/organizations" },
  { method: "GET" as const, url: "/api/v4/secrets", requestUrl: "/api/v4/secrets" }
];

const testGlobals = () => globalThis as unknown as { testServices?: unknown };

describe("INFISICAL_RUN_MODES route registration", () => {
  describe("with the api run mode (the shared test server)", () => {
    test("serves the status endpoint", async () => {
      const res = await testServer.inject({ method: "GET", url: "/api/status" });

      expect(res.statusCode).toBe(200);
      expect(JSON.parse(res.payload)).toHaveProperty("message", "Ok");
    });

    test("serves the product API", async () => {
      const res = await testServer.inject({ method: "GET", url: "/api/v1/admin/config" });

      expect(res.statusCode).toBe(200);
      expect(JSON.parse(res.payload)).toHaveProperty("config");
    });

    test.each(API_ROUTES)("registers $method $url", ({ method, url }) => {
      expect(testServer.hasRoute({ method, url })).toBe(true);
    });
  });

  describe("without the api run mode (a worker-only pod)", () => {
    let workerServer: Awaited<ReturnType<typeof main>>;
    let workerQueue: ReturnType<typeof queueServiceFactory>;
    let workerRedis: ReturnType<typeof buildRedisFromConfig>;
    let sharedTestServices: unknown;
    const originalRunModes = process.env.INFISICAL_RUN_MODES;

    beforeAll(async () => {
      // Spec files run in a separate module graph from the shared test server, so re-initializing
      // the env config here rebinds only this file's copy — the running test server is untouched.
      initLogger();
      process.env.INFISICAL_RUN_MODES = `${RunMode.GeneralWorkers},${RunMode.SecretScanning}`;
      const envConfig = await initEnvConfig(testHsmService, testKmsRootConfigDAL, testSuperAdminDAL);

      workerQueue = queueServiceFactory(envConfig);
      workerRedis = buildRedisFromConfig(envConfig);

      // registerRoutes publishes its own services to globalThis.testServices under NODE_ENV=test,
      // so booting a second server hands every later spec this pod's services — which point at a
      // different smtp mock and belong to a server this file closes.
      sharedTestServices = testGlobals().testServices;

      workerServer = await main({
        db: testDb,
        smtp: mockSmtpServer(),
        queue: workerQueue,
        keyStore: keyStoreFactory(envConfig, keyValueStoreDALFactory(testDb)),
        redis: workerRedis,
        clickhouse: buildClickHouseFromConfig(envConfig),
        hsmService: testHsmService,
        kmsRootConfigDAL: testKmsRootConfigDAL,
        superAdminDAL: testSuperAdminDAL,
        envConfig
      });

      testGlobals().testServices = sharedTestServices;
    });

    afterAll(async () => {
      // main.ts closes the server and shuts the queue down separately; the server's onClose hook
      // does not touch the queue. Skipping it leaves this pod's BullMQ workers consuming jobs from
      // later specs, since the whole e2e suite shares one fork and one Redis.
      await workerServer?.close();
      await workerQueue?.shutdown();
      await workerRedis?.quit();
      testGlobals().testServices = sharedTestServices;

      if (originalRunModes === undefined) delete process.env.INFISICAL_RUN_MODES;
      else process.env.INFISICAL_RUN_MODES = originalRunModes;
      await initEnvConfig(testHsmService, testKmsRootConfigDAL, testSuperAdminDAL);
    });

    test("still serves the status endpoint so probes keep working", async () => {
      const res = await workerServer.inject({ method: "GET", url: "/api/status" });

      expect(res.statusCode).toBe(200);
      expect(JSON.parse(res.payload)).toHaveProperty("message", "Ok");
    });

    test.each(API_ROUTES)("does not register $method $url", async ({ method, url, requestUrl }) => {
      expect(workerServer.hasRoute({ method, url })).toBe(false);

      // 404 rather than 401: the route is absent, not merely refusing the caller.
      const res = await workerServer.inject({ method, url: requestUrl });
      expect(res.statusCode).toBe(404);
    });
  });
});

import { randomUUID } from "node:crypto";

import { Redis } from "ioredis";
import { beforeEach, describe, expect, test } from "vitest";

import { IdentityAuthMethod } from "@app/db/schemas";
import { KeyStorePrefixes, TKeyStoreFactory } from "@app/keystore/keystore";
import {
  clearIdentityLockoutsForAuthMethod,
  clearIdentityLockoutState,
  getIdentityActiveLockoutAuthMethods,
  getIdentityLockoutState,
  persistIdentityLockoutState
} from "@app/services/identity/identity-fns";

// Against the real Redis the e2e environment boots, because what is under test is server-side: the
// write is a Lua script, expiry is Redis's own, and the regression this guards was a SCAN issued by
// ioredis. The in-memory keystore the unit tests use fakes all three.
declare const testRedis: Redis;
declare const testKeyStore: TKeyStoreFactory;

const commandCalls = async (command: string) => {
  const info = await testRedis.info("commandstats");
  const line = info.split("\n").find((row) => row.startsWith(`cmdstat_${command}:`));
  // Anchored on the first field: a greedy match picks up the trailing failed_calls= instead and
  // reads every counter as zero, which makes an assertion built on this pass vacuously.
  return line ? Number(/^[^:]+:calls=(\d+),/.exec(line)?.[1] ?? 0) : 0;
};

const indexKey = (id: string) => KeyStorePrefixes.IdentityLockoutIndex(id);
const itemKey = (id: string, authMethod: string, slug: string) =>
  KeyStorePrefixes.IdentityLockoutState(id, authMethod, slug);

const lockout = (identityId: string, slug: string, expiryInSeconds: number, lockedOut: boolean) =>
  persistIdentityLockoutState(
    { identityId, authMethod: IdentityAuthMethod.LDAP_AUTH, slug, expiryInSeconds },
    { lockedOut, failedAttempts: lockedOut ? 3 : 1 },
    testKeyStore
  );

let identityId: string;

beforeEach(async () => {
  identityId = randomUUID();
  await testRedis.del(indexKey(identityId));
});

describe("identity lockout keystore", () => {
  test("a lockout round-trips, and both the item and the index expire on their own", async () => {
    await lockout(identityId, "alice", 300, true);

    await expect(
      getIdentityLockoutState({ identityId, authMethod: IdentityAuthMethod.LDAP_AUTH, slug: "alice" }, testKeyStore)
    ).resolves.toEqual({ lockedOut: true, failedAttempts: 3 });

    await expect(getIdentityActiveLockoutAuthMethods(identityId, testKeyStore)).resolves.toEqual([
      IdentityAuthMethod.LDAP_AUTH
    ]);

    // Neither may outlive its lockout: a key with no TTL is a leak nothing reclaims.
    const itemTtl = await testRedis.ttl(itemKey(identityId, IdentityAuthMethod.LDAP_AUTH, "alice"));
    const idxTtl = await testRedis.ttl(indexKey(identityId));
    expect(itemTtl).toBeGreaterThan(0);
    expect(itemTtl).toBeLessThanOrEqual(300);
    expect(idxTtl).toBeGreaterThan(0);
  });

  test("the index expiry only ever grows, so a short write cannot cut a long lockout short", async () => {
    await lockout(identityId, "long", 3600, true);
    await lockout(identityId, "short", 30, true);

    expect(await testRedis.ttl(indexKey(identityId))).toBeGreaterThan(300);
  });

  test("a failure counter is never indexed, so spraying slugs cannot enlarge the list read", async () => {
    // LDAP slugs are caller-supplied usernames. Counters are addressed directly by login and are of
    // no use to the list endpoints, so keeping them out of the index is what bounds that read.
    for (let i = 0; i < 500; i += 1) {
      // eslint-disable-next-line no-await-in-loop
      await lockout(identityId, `sprayed-${i}`, 60, false);
    }

    expect(await testRedis.zcard(indexKey(identityId))).toBe(0);
    await expect(getIdentityActiveLockoutAuthMethods(identityId, testKeyStore)).resolves.toEqual([]);

    // The counters themselves are still readable by the login path that knows their slug.
    await expect(
      getIdentityLockoutState({ identityId, authMethod: IdentityAuthMethod.LDAP_AUTH, slug: "sprayed-1" }, testKeyStore)
    ).resolves.toEqual({ lockedOut: false, failedAttempts: 1 });

    // ...and one real lockout among them is still found, without the spray inflating the index.
    await lockout(identityId, "victim", 300, true);
    expect(await testRedis.zcard(indexKey(identityId))).toBe(1);
    await expect(getIdentityActiveLockoutAuthMethods(identityId, testKeyStore)).resolves.toEqual([
      IdentityAuthMethod.LDAP_AUTH
    ]);
  });

  test("a member that outlives its item is not reported, before anything prunes it", async () => {
    // Redis expires the item on its own but cannot expire an index member, so the index is briefly
    // stale. Reads range by score, which is why that staleness is never visible.
    await lockout(identityId, "alice", 300, true);
    await testRedis.del(itemKey(identityId, IdentityAuthMethod.LDAP_AUTH, "alice"));
    await testRedis.zadd(indexKey(identityId), Date.now() - 1_000, `${IdentityAuthMethod.LDAP_AUTH}:alice`);

    expect(await testRedis.zcard(indexKey(identityId))).toBe(1);
    await expect(getIdentityActiveLockoutAuthMethods(identityId, testKeyStore)).resolves.toEqual([]);
  });

  test("expired members are pruned on write, in one command and with nothing left behind", async () => {
    const stale = Array.from({ length: 400 }, (_, i) => [
      Date.now() - 1_000,
      `${IdentityAuthMethod.LDAP_AUTH}:old-${i}`
    ]);
    await testRedis.zadd(indexKey(identityId), ...stale.flat());
    expect(await testRedis.zcard(indexKey(identityId))).toBe(400);

    // A single write, not a batch that has to be repeated: the index is ordered by deadline, so one
    // range removal takes every expired member regardless of how many there are.
    await lockout(identityId, "alice", 300, true);

    expect(await testRedis.zcard(indexKey(identityId))).toBe(1);
    await expect(getIdentityActiveLockoutAuthMethods(identityId, testKeyStore)).resolves.toEqual([
      IdentityAuthMethod.LDAP_AUTH
    ]);
  });

  test("clearing one slug removes the item and its index member together", async () => {
    await lockout(identityId, "alice", 300, true);
    await lockout(identityId, "bob", 300, true);

    await clearIdentityLockoutState(
      { identityId, authMethod: IdentityAuthMethod.LDAP_AUTH, slug: "alice" },
      testKeyStore
    );

    expect(await testRedis.exists(itemKey(identityId, IdentityAuthMethod.LDAP_AUTH, "alice"))).toBe(0);
    expect(await testRedis.zscore(indexKey(identityId), `${IdentityAuthMethod.LDAP_AUTH}:alice`)).toBeNull();
    expect(await testRedis.zscore(indexKey(identityId), `${IdentityAuthMethod.LDAP_AUTH}:bob`)).not.toBeNull();
  });

  test("clearing a method removes every locked slug for it, and leaves other methods alone", async () => {
    await lockout(identityId, "alice", 300, true);
    await lockout(identityId, "bob", 300, true);
    await persistIdentityLockoutState(
      {
        identityId,
        authMethod: IdentityAuthMethod.UNIVERSAL_AUTH,
        slug: "client-a",
        expiryInSeconds: 300
      },
      { lockedOut: true, failedAttempts: 3 },
      testKeyStore
    );

    await expect(
      clearIdentityLockoutsForAuthMethod(identityId, IdentityAuthMethod.LDAP_AUTH, testKeyStore)
    ).resolves.toBe(2);

    expect(await testRedis.exists(itemKey(identityId, IdentityAuthMethod.LDAP_AUTH, "alice"))).toBe(0);
    expect(await testRedis.exists(itemKey(identityId, IdentityAuthMethod.LDAP_AUTH, "bob"))).toBe(0);
    await expect(getIdentityActiveLockoutAuthMethods(identityId, testKeyStore)).resolves.toEqual([
      IdentityAuthMethod.UNIVERSAL_AUTH
    ]);
  });

  test("no lockout path issues a SCAN, whatever the keyspace holds", async () => {
    // The incident: one SCAN MATCH walk of the whole keyspace per identity on every list row. MATCH
    // is a post-filter, so the cost tracked the keyspace, not the number of lockouts.
    const decoys: string[] = [];
    const pipeline = testRedis.pipeline();
    for (let i = 0; i < 2_000; i += 1) {
      const key = `lockout-scan-decoy:${identityId}:${i}`;
      decoys.push(key);
      pipeline.set(key, "1", "EX", 120);
    }
    await pipeline.exec();

    await lockout(identityId, "alice", 300, true);

    const scanBefore = await commandCalls("scan");
    const rangeBefore = await commandCalls("zrangebyscore");

    const LIST_READS = 10;
    for (let i = 0; i < LIST_READS; i += 1) {
      // eslint-disable-next-line no-await-in-loop
      await getIdentityActiveLockoutAuthMethods(identityId, testKeyStore);
    }
    await getIdentityLockoutState(
      { identityId, authMethod: IdentityAuthMethod.LDAP_AUTH, slug: "alice" },
      testKeyStore
    );
    await clearIdentityLockoutsForAuthMethod(identityId, IdentityAuthMethod.LDAP_AUTH, testKeyStore);

    // Proves the counter is being read at all before the SCAN assertion leans on it: a broken parser
    // reports zero for every command, which would make that assertion pass having measured nothing.
    // It also pins the cost -- one keyed range read per list row, and no more.
    expect(await commandCalls("zrangebyscore")).toBe(rangeBefore + LIST_READS);
    expect(await commandCalls("scan")).toBe(scanBefore);

    await testRedis.del(...decoys);
  });
});

import { describe, expect, test } from "vitest";

import { getMigrationBootDirection } from "./auto-start-migrations-fns";

describe("getMigrationBootDirection", () => {
  test("returns 'current' when applied and bundled match exactly", () => {
    const result = getMigrationBootDirection({
      appliedMigrationNames: ["20260101000000_a.mjs", "20260102000000_b.mjs"],
      bundledMigrationNames: ["20260101000000_a.mjs", "20260102000000_b.mjs"]
    });
    expect(result.direction).toBe("current");
  });

  test("returns 'behind' when the image bundles migrations not yet applied", () => {
    const result = getMigrationBootDirection({
      appliedMigrationNames: ["20260101000000_a.mjs"],
      bundledMigrationNames: ["20260101000000_a.mjs", "20260102000000_b.mjs"]
    });
    expect(result.direction).toBe("behind");
    expect(result.pendingMigrationNames).toEqual(["20260102000000_b.mjs"]);
  });

  test("returns 'ahead' on a clean rolling deploy (DB has strictly-newer migrations, nothing pending)", () => {
    const result = getMigrationBootDirection({
      appliedMigrationNames: ["20260101000000_a.mjs", "20260102000000_b.mjs", "20260103000000_c.mjs"],
      bundledMigrationNames: ["20260101000000_a.mjs", "20260102000000_b.mjs"]
    });
    expect(result.direction).toBe("ahead");
    expect(result.unknownAppliedMigrationNames).toEqual(["20260103000000_c.mjs"]);
  });

  // INC-62: a backdated migration merged after later-timestamped ones (common on long-lived branches).
  // The DB has an unknown migration whose timestamp is OLDER than the image's newest bundled migration,
  // but the image has nothing pending. Its bundled set is still a strict subset of what's applied, so it
  // must boot ('ahead'), not fail ('invalid').
  test("returns 'ahead' for an interleaved/backdated unknown migration when nothing is pending", () => {
    const result = getMigrationBootDirection({
      appliedMigrationNames: [
        "20260101000000_a.mjs",
        "20260102000000_b.mjs",
        "20260102120000_backdated.mjs", // older than the image's newest bundled migration
        "20260103000000_c.mjs"
      ],
      bundledMigrationNames: ["20260101000000_a.mjs", "20260102000000_b.mjs", "20260103000000_c.mjs"]
    });
    expect(result.direction).toBe("ahead");
    expect(result.unknownAppliedMigrationNames).toEqual(["20260102120000_backdated.mjs"]);
    expect(result.pendingMigrationNames).toEqual([]);
  });

  test("returns 'invalid' only on a true fork (DB has unknown migrations AND the image has pending ones)", () => {
    const result = getMigrationBootDirection({
      appliedMigrationNames: ["20260101000000_a.mjs", "20260102000000_db_only.mjs"],
      bundledMigrationNames: ["20260101000000_a.mjs", "20260103000000_image_only.mjs"]
    });
    expect(result.direction).toBe("invalid");
    expect(result.unknownAppliedMigrationNames).toEqual(["20260102000000_db_only.mjs"]);
    expect(result.pendingMigrationNames).toEqual(["20260103000000_image_only.mjs"]);
  });
});

import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";

import { type Knex } from "knex";
import { afterEach, describe, expect, it, vi } from "vitest";

import {
  getAppliedMigrationNames,
  getMigrationBootDirection,
  getMigrationBootState
} from "./auto-start-migrations-fns";

const migrationTableName = "infisical_migrations";
const migrationConfig = {
  directory: "",
  loadExtensions: [".mjs", ".ts"],
  tableName: migrationTableName
};

const testMigrationNames = {
  first: "20260101000000_first.mjs",
  second: "20260102000000_second.mjs",
  renamedSecond: "20260102000000_renamed-second.mjs",
  future: "20260103000000_future.mjs"
};

let tempDirs: string[] = [];

const writeBundledMigrations = async (migrationNames: string[]) => {
  const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "infisical-migrations-"));
  tempDirs.push(tempDir);

  await Promise.all(migrationNames.map((migrationName) => fs.writeFile(path.join(tempDir, migrationName), "")));

  return {
    ...migrationConfig,
    directory: tempDir
  };
};

const buildDbWithMissingMigrationTable = () =>
  ({
    schema: {
      hasTable: vi.fn().mockResolvedValue(false)
    }
  }) as unknown as Knex;

const buildDbWithAppliedMigrations = (migrationNames: string[]) => {
  const orderBy = vi.fn().mockResolvedValue(migrationNames.map((name) => ({ name })));
  const select = vi.fn().mockReturnValue({ orderBy });
  const db = vi.fn().mockReturnValue({ select });

  return Object.assign(db, {
    schema: {
      hasTable: vi.fn().mockResolvedValue(true)
    }
  }) as unknown as Knex;
};

afterEach(async () => {
  await Promise.all(tempDirs.map((tempDir) => fs.rm(tempDir, { force: true, recursive: true })));
  tempDirs = [];
  vi.restoreAllMocks();
});

describe("getMigrationBootDirection", () => {
  it("returns current when applied migrations match bundled migrations", () => {
    expect(
      getMigrationBootDirection({
        appliedMigrationNames: [testMigrationNames.first, testMigrationNames.second],
        bundledMigrationNames: [testMigrationNames.first, testMigrationNames.second]
      })
    ).toEqual({
      direction: "current",
      unknownAppliedMigrationNames: [],
      pendingMigrationNames: []
    });
  });

  it("returns behind when bundled migrations have not been applied yet", () => {
    expect(
      getMigrationBootDirection({
        appliedMigrationNames: [testMigrationNames.first],
        bundledMigrationNames: [testMigrationNames.first, testMigrationNames.second]
      })
    ).toEqual({
      direction: "behind",
      unknownAppliedMigrationNames: [],
      pendingMigrationNames: [testMigrationNames.second]
    });
  });

  it("returns ahead when the database has migrations not bundled in this image", () => {
    expect(
      getMigrationBootDirection({
        appliedMigrationNames: [testMigrationNames.first, testMigrationNames.second, testMigrationNames.future],
        bundledMigrationNames: [testMigrationNames.first, testMigrationNames.second]
      })
    ).toEqual({
      direction: "ahead",
      unknownAppliedMigrationNames: [testMigrationNames.future],
      pendingMigrationNames: []
    });
  });

  it("treats first deployment as behind when no migrations have been applied", () => {
    expect(
      getMigrationBootDirection({
        appliedMigrationNames: [],
        bundledMigrationNames: [testMigrationNames.first, testMigrationNames.second]
      })
    ).toEqual({
      direction: "behind",
      unknownAppliedMigrationNames: [],
      pendingMigrationNames: [testMigrationNames.first, testMigrationNames.second]
    });
  });

  it("treats a restored forward image as current after the rollback migration is reapplied", () => {
    expect(
      getMigrationBootDirection({
        appliedMigrationNames: [testMigrationNames.first, testMigrationNames.second, testMigrationNames.future],
        bundledMigrationNames: [testMigrationNames.first, testMigrationNames.second, testMigrationNames.future]
      })
    ).toEqual({
      direction: "current",
      unknownAppliedMigrationNames: [],
      pendingMigrationNames: []
    });
  });

  it("treats a manually applied migration from another image as ahead", () => {
    expect(
      getMigrationBootDirection({
        appliedMigrationNames: [testMigrationNames.first, testMigrationNames.second, testMigrationNames.future],
        bundledMigrationNames: [testMigrationNames.first, testMigrationNames.second]
      }).direction
    ).toBe("ahead");
  });

  it("treats a manually removed migration record as behind", () => {
    expect(
      getMigrationBootDirection({
        appliedMigrationNames: [testMigrationNames.first],
        bundledMigrationNames: [testMigrationNames.first, testMigrationNames.second]
      }).direction
    ).toBe("behind");
  });

  it("treats an unknown historical migration as invalid instead of rollback-safe ahead", () => {
    expect(
      getMigrationBootDirection({
        appliedMigrationNames: [testMigrationNames.first, testMigrationNames.renamedSecond],
        bundledMigrationNames: [testMigrationNames.first, testMigrationNames.second, testMigrationNames.future]
      })
    ).toMatchObject({
      direction: "invalid",
      unknownAppliedMigrationNames: [testMigrationNames.renamedSecond],
      pendingMigrationNames: [testMigrationNames.second, testMigrationNames.future]
    });
  });

  it("treats mixed unknown future migrations and missing bundled migrations as invalid", () => {
    expect(
      getMigrationBootDirection({
        appliedMigrationNames: [testMigrationNames.first, testMigrationNames.future],
        bundledMigrationNames: [testMigrationNames.first, testMigrationNames.second]
      })
    ).toMatchObject({
      direction: "invalid",
      unknownAppliedMigrationNames: [testMigrationNames.future],
      pendingMigrationNames: [testMigrationNames.second]
    });
  });
});

describe("getMigrationBootState", () => {
  it("returns behind on first deployment when the migration table does not exist", async () => {
    const testMigrationConfig = await writeBundledMigrations([testMigrationNames.first, testMigrationNames.second]);

    await expect(
      getMigrationBootState({
        db: buildDbWithMissingMigrationTable(),
        migrationConfig: testMigrationConfig
      })
    ).resolves.toEqual({
      direction: "behind",
      unknownAppliedMigrationNames: [],
      pendingMigrationNames: [testMigrationNames.first, testMigrationNames.second]
    });
  });

  it("returns ahead when a newer migration was deployed and the app code was rolled back", async () => {
    const testMigrationConfig = await writeBundledMigrations([testMigrationNames.first, testMigrationNames.second]);

    await expect(
      getMigrationBootState({
        db: buildDbWithAppliedMigrations([
          testMigrationNames.first,
          testMigrationNames.second,
          testMigrationNames.future
        ]),
        migrationConfig: testMigrationConfig
      })
    ).resolves.toMatchObject({
      direction: "ahead",
      unknownAppliedMigrationNames: [testMigrationNames.future]
    });
  });

  it("propagates database errors when the database is unavailable", async () => {
    const testMigrationConfig = await writeBundledMigrations([testMigrationNames.first]);
    const db = {
      schema: {
        hasTable: vi.fn().mockRejectedValue(new Error("connect ECONNREFUSED"))
      }
    } as unknown as Knex;

    await expect(
      getMigrationBootState({
        db,
        migrationConfig: testMigrationConfig
      })
    ).rejects.toThrow("connect ECONNREFUSED");
  });
});

describe("getAppliedMigrationNames", () => {
  it("returns an empty list when the migration table does not exist", async () => {
    await expect(getAppliedMigrationNames(buildDbWithMissingMigrationTable(), migrationTableName)).resolves.toEqual([]);
  });
});

# React + TypeScript + Vite

This template provides a minimal setup to get React working in Vite with HMR and some ESLint rules.

Currently, two official plugins are available:

- [@vitejs/plugin-react](https://github.com/vitejs/vite-plugin-react/blob/main/packages/plugin-react/README.md) uses [Babel](https://babeljs.io/) for Fast Refresh
- [@vitejs/plugin-react-swc](https://github.com/vitejs/vite-plugin-react-swc) uses [SWC](https://swc.rs/) for Fast Refresh

## Expanding the ESLint configuration

If you are developing a production application, we recommend updating the configuration to enable type aware lint rules:

- Configure the top-level `parserOptions` property like this:

```js
export default tseslint.config({
  languageOptions: {
    // other options...
    parserOptions: {
      project: ['./tsconfig.node.json', './tsconfig.app.json'],
      tsconfigRootDir: import.meta.dirname,
    },
  },
})
```

- Replace `tseslint.configs.recommended` to `tseslint.configs.recommendedTypeChecked` or `tseslint.configs.strictTypeChecked`
- Optionally add `...tseslint.configs.stylisticTypeChecked`
- Install [eslint-plugin-react](https://github.com/jsx-eslint/eslint-plugin-react) and update the config:

```js
// eslint.config.js
import react from 'eslint-plugin-react'

export default tseslint.config({
  // Set the react version
  settings: { react: { version: '18.3' } },
  plugins: {
    // Add the react plugin
    react,
  },
  rules: {
    // other rules...
    // Enable its recommended rules
    ...react.configs.recommended.rules,
    ...react.configs['jsx-runtime'].rules,
  },
})
```
